targets.expr:
WITH (
  recommendations = kompass_rs_recommendations{
    namespace="$namespace",
    workload_name="$workload_name",
    workload_kind="$workload_kind",
    container=~"$container",
    resource_type="jvm_max_heap",
    resource_source="desired",
    mode="live",
    execution_state="successful"
  },
  latest = max by(resource_id,container) (
    last_over_time(recommendations[1d])
    and topk by(resource_id,container) (1, tlast_over_time(recommendations[1d]))
  ),
  running = max by(resource_id,container) (
    kompass_pod_info{
      namespace="$namespace",workload_name="$workload_name",workload_kind="$workload_kind",
      container=~"$container",status="running"
    }
  )
)
sum by(resource_id) ((latest / 1024 / 1024) and on(resource_id,container) running)

kube_horizontalpodautoscaler_spec_min_replicas{namespace="$namespace"}
  * on (namespace, horizontalpodautoscaler)
    group_left(scaletargetref_kind, scaletargetref_name)
    kube_horizontalpodautoscaler_info{
      namespace="$namespace",
      scaletargetref_kind="Deployment",
      scaletargetref_name="$workload_name"
    }

